// The content catalog (content_catalog.json, generated by android-app-quran-player/.setup/
// make_content_catalog.py and shared with the Android app's data/ContentCatalog.kt): which
// translations, word-meaning languages, tafsirs and reciters exist, with their sources.
//
// Settings store an edition's stable id, never its name. Everything here is pure, so the same
// rules are unit-tested without a browser; services/content.js does the loading.

export const TRANSLATION_STYLES = Object.freeze({
  WORDS: 'words', // word-by-word meanings only
  AYAH: 'ayah', // the whole ayah's translation only
  BOTH: 'both',
});

/** The style the two existing switches add up to (neither on reads as words, the default). */
export function styleOf(settings) {
  const words = settings.showWordTranslations;
  const ayah = settings.showAyahTranslation;
  if (words && ayah) return TRANSLATION_STYLES.BOTH;
  if (ayah) return TRANSLATION_STYLES.AYAH;
  return TRANSLATION_STYLES.WORDS;
}

/** The switches a style sets: {showWordTranslations, showAyahTranslation}. */
export function switchesFor(style) {
  return {
    showWordTranslations: style !== TRANSLATION_STYLES.AYAH,
    showAyahTranslation: style !== TRANSLATION_STYLES.WORDS,
  };
}

const follow = (catalog, id) => {
  let seen = 0;
  while (id && catalog.retired?.[id] && seen++ < 8) id = catalog.retired[id];
  return id;
};

/** The edition for a saved id: a retired id follows its replacement; unknown falls back to the default. */
export function translationById(catalog, id) {
  const wanted = follow(catalog, id);
  return catalog.translations.find((t) => t.id === wanted)
    ?? catalog.translations.find((t) => t.id === catalog.defaults.translation);
}

/** The tafsir for a saved id, or null for none (or one that no longer exists). */
export function tafsirById(catalog, id) {
  if (!id) return null;
  const wanted = follow(catalog, id);
  return catalog.tafsirs.find((t) => t.id === wanted) ?? null;
}

/** A word-meaning language the catalog has, or the default (English, bundled). */
export function wordMeaningsById(catalog, id) {
  return catalog.wordMeanings.find((w) => w.id === id)
    ?? catalog.wordMeanings.find((w) => w.id === catalog.defaults.wordMeanings);
}

export function languageName(catalog, code, { native = false } = {}) {
  const l = catalog.languages[code];
  if (!l) return code;
  return native && l.nativeName && l.nativeName !== l.name ? `${l.nativeName} (${l.name})` : l.name;
}

export const isRtl = (catalog, code) => Boolean(catalog.languages[code]?.rtl);

/** Languages that have at least one translation, English first, then by English name. */
export function translationLanguages(catalog) {
  const codes = [...new Set(catalog.translations.map((t) => t.language))];
  return codes.sort((a, b) => (a === 'en' ? -1 : b === 'en' ? 1 : languageName(catalog, a).localeCompare(languageName(catalog, b))));
}

/** A language's translations: bundled, then recommended, then the rest, each by name. */
export function translationsIn(catalog, code) {
  return catalog.translations
    .filter((t) => t.language === code)
    .sort((a, b) => Number(Boolean(b.bundled)) - Number(Boolean(a.bundled))
      || Number(b.recommended) - Number(a.recommended)
      || a.name.localeCompare(b.name));
}

/** Case- and accent-insensitive search over name, author and language. */
export function searchTranslations(catalog, query) {
  const fold = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
  const q = fold(query).trim();
  if (!q) return catalog.translations;
  return catalog.translations.filter((t) =>
    [t.name, t.author, t.language, languageName(catalog, t.language), catalog.languages[t.language]?.nativeName].some((f) => fold(f).includes(q)));
}

/** Tafsirs, the reader's translation language first. */
export function tafsirsFor(catalog, preferLanguage) {
  return [...catalog.tafsirs].sort((a, b) =>
    Number(b.language === preferLanguage) - Number(a.language === preferLanguage)
    || Number(b.language === 'en') - Number(a.language === 'en')
    || a.language.localeCompare(b.language)
    || Number(b.recommended) - Number(a.recommended)
    || a.name.localeCompare(b.name));
}

/** "Saheeh International · Tanzil.net", for credits and the Sources list. */
export const creditOf = (edition) => (edition ? `${edition.name} · ${edition.source}` : '');

// -- provider text ---------------------------------------------------------------------------

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };

export function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+\d*);/gi, (m, e) => {
    if (e[0] === '#') {
      const n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(n) && n > 0 && n < 0x110000 ? String.fromCodePoint(n) : '';
    }
    return ENTITIES[e.toLowerCase()] ?? m;
  });
}

/**
 * A translation as plain text. Quran.com marks footnotes `<sup foot_note=N>1</sup>`; the
 * footnote text isn't fetched, so the marker is dropped rather than left as a stray digit.
 * Any other markup is removed, never rendered: this text is only ever set as textContent.
 */
export function plainTranslation(raw) {
  if (raw == null) return '';
  return decodeEntities(String(raw)
    .replace(/<sup\b[^>]*>[\s\S]*?<\/sup>/gi, '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]*>/g, ''))
    .replace(/\s+([,.;:!?،؛۔])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Word meanings for one ayah from a Quran.com verse (`words=true&language=…`), aligned to the
 * content words of our own text by `position`. Our text marks 2:181's number glyph as the end
 * where Quran.com calls it a word, so alignment goes by position, never by counting.
 * A word with no meaning in [languageName] is null, and the reader falls back to English for it.
 */
export function alignWordMeanings(ourWords, verse, languageName) {
  const theirs = new Map();
  for (const w of verse?.words ?? []) if (w.char_type_name === 'word') theirs.set(w.position, w);
  return ourWords.filter((w) => w.char_type !== 'end').map((w) => {
    const t = theirs.get(w.position)?.translation;
    if (!t?.text) return null;
    if (languageName && t.language_name && t.language_name.toLowerCase() !== languageName) return null;
    return plainTranslation(t.text) || null;
  });
}
